Current task: Fix build crash (Expected ident) in preview route

Root cause
You wrote this into a TypeScript file:
TypeScript# (ONLY replace import line at top manually after paste)
That is invalid syntax in JS/TS.


# is NOT a comment in TypeScript


It breaks the parser → Expected ident



Fix (clean + safe)
Bash — overwrite ONLY route.ts correctly
Bashcat << 'EOF' > app/api/dev/preview/route.ts
import { NextRequest } from "next/server";
import * as esbuild from "esbuild";
import fs from "fs";
import path from "path";
import { resolveEntry } from "./resolveEntry";

const ROOT = process.cwd();

function getProjectRoot(projectId: string) {
  return path.join(ROOT, "runtime/workspaces/default/projects", projectId);
}

function readAllFiles(dir: string, base = ""): Record<string, string> {
  const out: Record<string, string> = {};
  const items = fs.readdirSync(dir);

  for (const item of items) {
    const full = path.join(dir, item);
    const rel = path.join(base, item);

    const stat = fs.statSync(full);

    if (stat.isDirectory()) {
      Object.assign(out, readAllFiles(full, rel));
    } else {
      if (rel.endsWith(".d.ts")) continue;
      out[rel] = fs.readFileSync(full, "utf-8");
    }
  }

  return out;
}

async function bundle(files: Record<string, string>, entry: string) {
  const tempDir = path.join(ROOT, ".preview-temp");
  fs.rmSync(tempDir, { recursive: true, force: true });
  fs.mkdirSync(tempDir, { recursive: true });

  for (const [file, content] of Object.entries(files)) {
    const full = path.join(tempDir, file);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content);
  }

  const result = await esbuild.build({
    entryPoints: [path.join(tempDir, entry)],
    bundle: true,
    write: false,
    platform: "browser",
    format: "iife",
    target: ["es2020"],
    jsx: "automatic",
    loader: {
      ".ts": "ts",
      ".tsx": "tsx",
      ".js": "js",
      ".jsx": "jsx",
      ".css": "empty",
    },
    external: ["react", "react-dom", "next", "next/*"],
    define: {
      "process.env.NODE_ENV": '"development"',
    },
  });

  return result.outputFiles[0].text;
}

function html(bundle: string) {
  return \`
<!doctype html>
<html>
  <body style="margin:0;background:#fff;">
    <div id="root"></div>

    <script src="https://unpkg.com/react@18/umd/react.development.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>

    <script>
      const root = ReactDOM.createRoot(document.getElementById("root"));
      \${bundle}
    </script>
  </body>
</html>
  \`;
}

export async function GET(req: NextRequest) {
  try {
    const projectId = req.nextUrl.searchParams.get("projectId");
    if (!projectId) {
      return new Response("Missing projectId", { status: 400 });
    }

    const root = getProjectRoot(projectId);
    if (!fs.existsSync(root)) {
      return new Response("Project not found", { status: 404 });
    }

    const files = readAllFiles(root);
    const entry = resolveEntry(files);

    const code = await bundle(files, entry);

    return new Response(html(code), {
      headers: {
        "Content-Type": "text/html",
        "Cache-Control": "no-store",
      },
    });
  } catch (err: any) {
    console.error(err);

    return new Response(
      \`<pre style="color:red;">\${err.message}</pre>\`,
      { headers: { "Content-Type": "text/html" } }
    );
  }
}
EOF

Then clean + restart
Bashrm -rf .next .preview-temp
npm run dev

Result


Build error gone


Preview route compiles


Entry resolver now actually used


System back to stable



